-- 13_comments.sql — self-documentation: every table, column, view, function and schema carries a description.
-- Generated from the documentation source; the PDF data dictionary reads these comments from the database.
comment on schema core is 'Identity, households (tenants), plans and entitlements, setup progress, consent, audit and data-rights records.';
comment on schema ref is 'Master data shared by all households: units, foods, allergens, diets, health rules, recipes, the kitchen-item catalogue, profiling questions and translations. Households can add custom foods and recipes.';
comment on schema hh is 'Household operational data: kitchens, storage locations, family members, kitchen items, food inventory and ledger, meals, shopping lists and alerts.';
comment on schema health is 'Sensitive member food and health requirements and the profiling answers they come from. Stricter access and audit than other data.';
comment on schema capture is 'Tier 2+ extension for photo, video, barcode and receipt capture. Present in the schema but locked by plan capabilities in the Free tier.';
comment on schema match is 'Meal matching: the explainable matching function and stored recommendation runs and results.';
comment on table capture.capture_assets is 'Files (photos, video, receipt images) attached to a capture session. Stores a storage key, not the file. Tier 2+; unused in Basic.';
comment on table capture.capture_detections is 'Items proposed from a capture (food or product, label, confidence, estimated quantity). The user accepts or rejects each one; accepted rows link to the inventory item created. Tier 2+.';
comment on table capture.capture_sessions is 'One capture event (image, video, barcode or receipt). Inserts are blocked unless the household plan includes the matching capability.';
comment on table core.membership_goals is 'What each account holder wants help with (from the About You screen).';
comment on table ref.help_goals is 'The goals a user can pick on the About You screen (decide what to cook, reduce food waste...).';
comment on table core.audit_log is 'Who did what to which record. Stores the table, row id and action only, never health values.';
comment on table core.capabilities is 'Catalogue of features a plan can switch on, for example inventory.manual or inventory.scan.barcode. The app tests capabilities, never tier numbers.';
comment on table core.consent_documents is 'Versioned legal documents users consent to: terms, privacy policy and health-data notice, per locale.';
comment on table core.consent_records is 'Append-only proof that a user granted or withdrew consent to a specific document version.';
comment on table core.data_requests is 'Account-holder requests to export or delete their data, with the status of each.';
comment on table core.devices is 'A user''s registered app installations (iOS, Android, web); identifies the source of offline changes.';
comment on table core.household_memberships is 'Account access to a household (a seat). Roles: owner, admin, kitchen_manager, member, limited. The seat count is limited by the plan (Free = 1). Not the same as a family member profile.';
comment on table core.household_subscriptions is 'The plan a household is on, with status and source (free, App Store, Google Play, web). At most one active subscription per household.';
comment on table core.households is 'The tenant. Everything a family owns hangs off a household. Holds default country, region, time zone, locale and measurement system.';
comment on table core.plan_capabilities is 'Which capabilities each plan includes.';
comment on table core.plan_limits is 'Numeric limits per plan, for example user_seats = 1 on Free. A missing row means unlimited.';
comment on table core.plans is 'The seven product tiers. Only tier 1 (WAMWins Basic, Free) is seeded.';
comment on table core.setup_progress is 'Progress of each guided setup step per household (pending, in progress, done, skipped), so users can resume setup.';
comment on table core.users is 'A person who can sign in. The id equals the authentication provider''s subject id. Credentials are held by the auth service, never here.';
comment on table health.member_allergies is 'Foods a family member must avoid for allergy reasons, with severity. A hard block in meal matching.';
comment on table health.member_dietary_requirements is 'Diets a member follows (vegetarian, vegan, gluten-free...). Blocks meals containing excluded foods.';
comment on table health.member_food_preferences is 'A member''s own food choices: like, dislike, avoid or prioritize, by category or specific food. Not medical.';
comment on table health.member_health_requirements is 'Health-related food requirements (low sodium, low sugar...). Produces warnings when a recipe''s nutrition breaks a rule.';
comment on table health.member_intolerances is 'Foods that upset a member but are not allergies. Produces a warning in meal matching.';
comment on table health.member_profile_answers is 'Exactly what was ticked on each profiling question. The source of truth from which the requirement records are derived.';
comment on table hh.alerts is 'Generated notices for a household: use-soon, low-stock, allergen conflict, system.';
comment on table hh.family_members is 'A person in the household (a profile), with or without a login; the subject of food and health requirements. Optionally linked to a user account.';
comment on table hh.household_item_settings is 'Per-household stock thresholds (par level, low-stock level) for a food, used by low-stock alerts.';
comment on table hh.household_settings is 'Per-household options such as the use-soon window (default 3 days) and whether low-stock alerts are on.';
comment on table hh.inventory_items is 'One stock lot of a food in a kitchen: quantity in base units, location, brand, dates, pack details and status. Quantity changes only through the ledger.';
comment on table hh.inventory_transactions is 'Append-only ledger of every stock change (add, purchase, use, consume, discard, adjust, transfers). The single source of stock history.';
comment on table hh.kitchen_items is 'Detail file of non-food kitchen items the household owns (appliances, cookware, glassware, dinnerware, facilities...), with quantity, size, capacity, material, location and condition.';
comment on table hh.kitchens is 'A kitchen belonging to the household, with its own country, region, time zone, language and measurement system. Exactly one is primary.';
comment on table hh.locations is 'Storage places within a kitchen as a tree (Pantry > Shelf 1..n, Refrigerator > Drawer...), with optional size and capacity.';
comment on table hh.meal_log_participants is 'Who ate a logged meal and how much.';
comment on table hh.meal_logs is 'Record of a meal cooked or eaten: recipe or free title, meal type, time, servings.';
comment on table hh.meal_plan_entries is 'Planned meals by date and meal type, optionally linked to a recipe.';
comment on table hh.member_kitchens is 'Links family members to the kitchens they use; one may be marked as home.';
comment on table hh.shopping_list_items is 'Items on a shopping list, from a master food or free text, with quantity, unit and bought status.';
comment on table hh.shopping_lists is 'Named shopping lists (default Grocery List).';
comment on table match.recommendation_results is 'Stored result per recipe for a run: fit score, availability, blocked flag and the reasons as JSON.';
comment on table match.recommendation_runs is 'A request for meal recommendations: who was eating and which engine version answered.';
comment on table ref.age_bands is 'Standard age ranges used when an exact birth date is not given, and to decide which profiling questions apply.';
comment on table ref.allergens is 'Allergens and intolerance triggers (milk, peanuts, lactose, gluten...) used by allergies, intolerances and food tagging.';
comment on table ref.appliance_types is 'Appliance types that recipes can require (oven, blender...). Linked from kitchen item types.';
comment on table ref.dietary_requirement_exclusions is 'Rules saying what each diet excludes: a food category, a specific food or an allergen.';
comment on table ref.dietary_requirement_types is 'Diets a member can follow.';
comment on table ref.food_categories is 'Hierarchical food categories (Protein > Poultry...).';
comment on table ref.food_item_aliases is 'Alternative names and spellings for foods, used for search and entry.';
comment on table ref.food_item_allergens is 'Which allergens each food contains or may contain.';
comment on table ref.food_item_nutrients is 'Nutrient values per 100 g for foods.';
comment on table ref.food_item_packages is 'Typical package sizes for a food by country (for example a 1 lb box in the U.S., 500 g in Germany).';
comment on table ref.food_items is 'Master file of foods. System foods are shared; a household can add its own custom foods.';
comment on table ref.health_requirement_rules is 'Nutrient thresholds behind each health food requirement (for example sodium per serving at most a limit). Starter values pending expert review.';
comment on table ref.health_requirement_types is 'Health-related food requirements a member can have.';
comment on table ref.i18n_labels is 'Translations for any master record, looked up by entity, id, field and locale with language fallback.';
comment on table ref.item_classes is 'Type tree classifying kitchen items (Glassware > Wine Glasses).';
comment on table ref.item_uses is 'Purposes an item serves (cooking, wine, beer, serving, dining...), grouped.';
comment on table ref.kitchen_item_sizes is 'Standard sizes offered for an item type (for example a 12 oz wine glass, an 8 quart stockpot).';
comment on table ref.kitchen_item_type_uses is 'Links each item type to its one primary use and any secondary uses.';
comment on table ref.kitchen_item_types is 'Master file of non-food kitchen items, each with a class, primary use, capacity type and optional regions where it is commonly asked about.';
comment on table ref.location_types is 'Kinds of storage place (pantry, shelf, refrigerator, freezer, cabinet, wine rack...) with temperature.';
comment on table ref.materials is 'Materials items are made of (glass, stainless steel, cast iron...).';
comment on table ref.nutrients is 'Nutrients tracked (calories, protein, sodium...).';
comment on table ref.products is 'Branded products identified by GTIN (barcode). Tier 2+ hook; unused in Basic.';
comment on table ref.profile_question_options is 'Answer options for a profiling question. Each option declares its effect (allergy, intolerance, diet, health, like, dislike, avoid, prioritize or none) and its target.';
comment on table ref.profile_questions is 'The question bank behind family health profiles. Data, not code; may carry an age window.';
comment on table ref.recipe_appliance_requirements is 'Appliances a recipe requires.';
comment on table ref.recipe_ingredients is 'Ingredients of a recipe with quantity, unit and base-unit quantity.';
comment on table ref.recipe_nutrients is 'Nutrition per serving for a recipe, used for health-requirement checks.';
comment on table ref.recipe_utensil_requirements is 'Utensil types a recipe needs (reserved for future matching).';
comment on table ref.recipes is 'Master recipes (system or household-custom) with servings, times and steps.';
comment on table ref.setup_steps is 'The eight guided setup steps and their order.';
comment on table ref.units is 'Units of measure with a dimension and a conversion factor to a base unit (g, ml, each); U.S. and metric.';
comment on table ref.utensil_types is 'Legacy utensil list superseded by ref.kitchen_item_types; kept for upgrade compatibility.';
