comment on function core.touch() is 'Trigger. On every insert or update sets updated_at and assigns a new rev (the sync cursor).';
comment on function core.active_plan(uuid) is 'Returns the plan id of the household''s active subscription.';
comment on function core.has_capability(uuid,text) is 'True when the household''s plan includes the capability.';
comment on function core.limit_value(uuid,text) is 'Numeric plan limit for the household, or null when unlimited.';
comment on function core.has_role(uuid,text[]) is 'True when the signed-in user has an active membership in the household with one of the roles.';
comment on function core.is_member(uuid) is 'True when the signed-in user has any active role in the household. Basis of row-level security.';
comment on function core.enforce_seat_limit() is 'Trigger on household_memberships. Refuses a new active or invited seat beyond the plan''s user_seats limit (error seat_limit_reached, hint upgrade_required).';
comment on function core.audit() is 'Trigger. Writes an audit_log row (table, row id, action, actor, household) for sensitive tables. Never records values.';
comment on function core.create_household(uuid,text,character,text,text,integer) is 'Onboarding bootstrap, one atomic call: creates the household, Free subscription, owner membership, primary kitchen, settings, the account holder''s family profile and all setup-progress rows. Enforces households_per_owner.';
comment on function ref.to_base(uuid,numeric) is 'Converts a quantity in a unit to base units.';
comment on function capture.require_capability() is 'Trigger on capture_sessions. Refuses the insert unless the plan includes the capability for that capture kind (error capability_required).';
comment on function hh.setup_utensils(uuid,text[]) is 'Setup answers for tools and utensils by code; idempotent.';
comment on function health.question_applies(uuid,numeric,numeric) is 'True when a question''s age window fits the member. Questions with no window apply to everyone; unknown ages see only unrestricted questions.';
comment on function hh.member_age_span(uuid) is 'Returns a member''s age range in years from the birth date, or from the chosen age band.';
comment on function health.questions_for_member(uuid) is 'The questions to ask a member, in order, with {name} filled in and an answered flag.';
comment on function core.set_setup_step(uuid,text,text) is 'Sets a setup step to pending, in_progress, done or skipped and stamps the completion time. Error: invalid_status.';
comment on function health.apply_profile_answers(uuid,uuid) is 'Rebuilds a member''s requirement records from their profiling answers: retires derived rows whose answer was removed, creates or revives rows for current answers. Manual rows are untouched.';
comment on function health.save_answers(uuid,uuid,text,text[]) is 'Saves the answers to one profiling question and rebuilds the member''s records. Validates the question applies by age, options exist, single-choice rules and that None is exclusive. Errors: unknown_question, question_not_applicable, unknown_option, single_choice_only, none_is_exclusive.';
comment on function hh.prepare_tx() is 'Trigger before a ledger insert. Converts to base units, applies the sign for the kind, stamps created_by.';
comment on function hh.block_tx_update() is 'Trigger. Refuses any update of a ledger row; corrections are new adjust rows.';
comment on function ref.label(text,uuid,text,text,text) is 'Translated text for any master record with fallback from locale (pt-BR) to language (pt) to the default name.';
comment on function ref.set_recipe_qty_base() is 'Trigger. Computes a recipe ingredient''s base-unit quantity.';
comment on function ref.category_ancestors(uuid) is 'Returns a food category and all its parents; used so excluding Protein excludes Poultry.';
comment on function ref.class_descendants(uuid) is 'Returns an item class and all its sub-classes.';
comment on function ref.class_path(uuid) is 'Readable path of an item class, for example Glassware > Wine Glasses.';
comment on function hh.setup_storage(uuid,text,text,integer) is 'Creates a storage area and optional numbered shelves (Pantry with 4 shelves creates Pantry, Shelf 1 to 4). Idempotent.';
comment on function hh.setup_appliances(uuid,text[]) is 'Setup answers for appliances by code; idempotent. Returns the number added.';
comment on function match.match_recipes(uuid,uuid[],uuid) is 'The matching engine. For the people eating (default everyone) and optionally one kitchen, returns each recipe with a 0-100 fit score, ingredient availability, a blocked flag and JSON reasons. See section 10.';
comment on function hh.apply_tx() is 'Trigger after a ledger insert. Adds the signed change to the lot''s quantity and sets status consumed or discarded at zero.';
comment on function hh.setup_checklist(uuid,text) is 'Master items for a class (for example glassware) relevant to the kitchen''s country, labelled in its language, with how many are already owned. Drives the tick-list setup screens.';
comment on function hh.add_inventory(uuid,text,numeric,text,uuid,date,date,text,text) is 'Simpler food entry into the primary kitchen (name, quantity, unit, optional location and dates).';
comment on function hh.kitchen_defaults() is 'Trigger on kitchens. Copies unset country, region, time zone, measurement system and locale from the household.';
comment on function hh.default_kitchen() is 'Trigger on inventory and kitchen items. Fills kitchen_id from the location, else the primary kitchen; rejects a location from a different kitchen (location_kitchen_mismatch).';
comment on function hh.add_kitchen(uuid,text,character,text,text,text,text) is 'Adds another kitchen with its own country, time zone, measurement system and language.';
comment on function hh.setup_items(uuid,uuid,jsonb) is 'Turns a screen of answers (JSON list of type, quantity, size, material, location...) into kitchen_items records. Safe to retry when each element carries an id.';
comment on function hh.add_food(uuid,uuid,text,numeric,text,uuid,date,date,text,numeric,text,integer,date,text) is 'Records a food with full detail (kitchen, location, dates, pack size, opened date). Accepts local names, aliases and translations. Creates a household custom food if none matches, then posts the first ledger entry.';
comment on function core.save_about_you(uuid,text,text,text[]) is 'Saves the About You screen in one call: display name, household role and goals; marks the about_you step done. Errors: not_a_member, name_required, unknown_goal.';
